CustomField.formula:
IF(
/*If Account is Country Parent, stores Solution_Executive__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Solution_Executive__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's Solution_Executive__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Solution_Executive__c,Solution_Executive__c))
